def is_interleave(s1: str, s2: str, s3: str) -> bool:
    len1 = len(s1)
    len2 = len(s2)
    len3 = len(s3)
    if len1 + len2 != len3:
        return False
    # Create a 2D list dp to keep track of possible interleavings
    dp = [[False] * (len2 + 1) for _ in range(len1 + 1)]
    # Base cases
    for i in range(len1 + 1):
        for j in range(len2 + 1):
            if i == 0 and j == 0:
                dp[i][j] = True  # Empty string is an interleaving
            elif i == 0:
                dp[i][j] = (s3[:j] == s2[:j])
            elif j == 0:
                dp[i][j] = (s3[:i] == s1[:i])
            else:
                if s3[i + j - 1] == s1[i - 1] or s3[i + j - 1] == s2[j - 1]:
                    dp[i][j] = dp[i - 1][j] or dp[i][j - 1]
                else:
                    dp[i][j] = False
    return dp[len1][len2]
